-- ----------------------------
-- Table structure for thk_wx_stock
-- ----------------------------
DROP TABLE IF EXISTS `thk_wx_stock`;
CREATE TABLE `thk_wx_stock`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `admin_id` int NOT NULL DEFAULT 0,
  `sort` int NOT NULL DEFAULT 0,
  `code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '代码',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '名称',
  `isdel` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除',
  `current_num` int NOT NULL DEFAULT 0 COMMENT '剩余持仓数',
  `current_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当前单价',
  `current_total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当前市值',
  `buy_total_num` int NOT NULL DEFAULT 0 COMMENT '买入总数',
  `buy_total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '买入花费总额',
  `sell_total_num` int NOT NULL DEFAULT 0 COMMENT '卖出总数',
  `sell_total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '卖出总金额',
  `commission_percentage` decimal(10, 5) NOT NULL DEFAULT 0.00000 COMMENT '佣金比',
  `commission_total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '总佣金',
  `transfer_total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '总过户费',
  `printing_total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '总印花税',
  `profit_and_loss` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '盈亏',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

