-- ----------------------------
-- Table structure for thk_wx_stock_recode
-- ----------------------------
DROP TABLE IF EXISTS `thk_wx_stock_recode`;
CREATE TABLE `thk_wx_stock_recode`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `admin_id` int NOT NULL DEFAULT 0,
  `stock_id` int NOT NULL,
  `stock_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `behavior` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0买入1卖出',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `num` int NOT NULL DEFAULT 0,
  `total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '总价',
  `commission_percentage` decimal(10, 5) NOT NULL DEFAULT 0.00000,
  `commission_price` decimal(10, 2) NOT NULL COMMENT '佣金',
  `transfer_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '过户费',
  `printing_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '印花税',
  `last_total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '此处减去或包含（佣金+过户+印花）',
  `create_time` bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 114 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

