-- ----------------------------
-- Triggers structure for table thk_wx_stock
-- ----------------------------
DROP TRIGGER IF EXISTS `stock_add`;
delimiter ;;
CREATE TRIGGER `stock_add` BEFORE INSERT ON `thk_wx_stock` FOR EACH ROW BEGIN
set new.current_num=new.buy_total_num-new.sell_total_num;
set new.current_total_price=new.current_num*new.current_price;
set new.profit_and_loss=new.sell_total_price+new.current_total_price-new.buy_total_price-new.commission_total_price-new.transfer_total_price-new.printing_total_price;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table thk_wx_stock
-- ----------------------------
DROP TRIGGER IF EXISTS `stock_edit`;
delimiter ;;
CREATE TRIGGER `stock_edit` BEFORE UPDATE ON `thk_wx_stock` FOR EACH ROW BEGIN
set new.current_num=new.buy_total_num-new.sell_total_num;
set new.current_total_price=new.current_num*new.current_price;
set new.profit_and_loss=new.sell_total_price+new.current_total_price-new.buy_total_price-new.commission_total_price-new.transfer_total_price-new.printing_total_price;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table thk_wx_stock_list
-- ----------------------------
DROP TRIGGER IF EXISTS `stock_list_edit`;
delimiter ;;
CREATE TRIGGER `stock_list_edit` AFTER UPDATE ON `thk_wx_stock_list` FOR EACH ROW BEGIN
update thk_wx_stock set current_price=new.current_price where code=new.code;
end
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table thk_wx_stock_recode
-- ----------------------------
DROP TRIGGER IF EXISTS `stock_recode_add`;
delimiter ;;
CREATE TRIGGER `stock_recode_add` BEFORE INSERT ON `thk_wx_stock_recode` FOR EACH ROW BEGIN
set new.total_price=0-new.num*new.price;
set new.last_total_price=new.total_price+new.commission_price+new.transfer_price+new.printing_price;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table thk_wx_stock_recode
-- ----------------------------
DROP TRIGGER IF EXISTS `stock_recode_edit`;
delimiter ;;
CREATE TRIGGER `stock_recode_edit` BEFORE INSERT ON `thk_wx_stock_recode` FOR EACH ROW BEGIN
set new.total_price=0-new.num*new.price;
set new.last_total_price=new.total_price+new.commission_price+new.transfer_price+new.printing_price;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
